'use strict';
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const table = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      table[i][j] = a[i - 1] === b[j - 1] ? table[i - 1][j - 1] + 1 :
        Math.max(table[i - 1][j], table[i][j - 1]);
    }
  }
  return table[a.length][b.length];
}

function referenceHunks(script, context) {
  const ranges = [];
  for (let i = 0; i < script.length; i++) {
    if (script[i].op === 'equal') continue;
    const start = Math.max(0, i - context);
    const end = Math.min(script.length, i + context + 1);
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous[1]) previous[1] = end;
    else ranges.push([start, end]);
  }
  return ranges.map(([start, end]) => {
    const before = script.slice(0, start);
    const entries = script.slice(start, end);
    const oldLines = entries.filter(e => e.op !== 'insert').length;
    const newLines = entries.filter(e => e.op !== 'delete').length;
    return {
      oldStart: before.filter(e => e.op !== 'insert').length + (oldLines ? 1 : 0),
      oldLines,
      newStart: before.filter(e => e.op !== 'delete').length + (newLines ? 1 : 0),
      newLines,
      lines: entries.map(e => ({ equal: ' ', delete: '-', insert: '+' })[e.op] + e.line),
    };
  });
}

const inputs = [Object.freeze([])];
let level = inputs;
for (let length = 1; length <= 4; length++) {
  const next = [];
  for (const input of level) {
    for (const line of ['', 'a', '+- ']) next.push(Object.freeze([...input, line]));
  }
  inputs.push(...next);
  level = next;
}
let pairs = 0;
for (const a of inputs) {
  for (const b of inputs) {
    const script = diffLines(a, b);
    assert.deepEqual(script, diffLines(a, b));
    assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
    assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
    assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
    let inserted = false;
    for (const e of script) {
      if (e.op === 'equal') inserted = false;
      if (e.op === 'insert') inserted = true;
      if (e.op === 'delete') assert.equal(inserted, false);
    }
    for (const context of [0, 1, 2, 3]) {
      const hunks = unifiedHunks(a, b, { context });
      assert.deepEqual(hunks, referenceHunks(script, context));
      for (const hunk of hunks) {
        Object.freeze(hunk.lines);
        Object.freeze(hunk);
      }
      Object.freeze(hunks);
      assert.deepEqual(applyHunks(a, hunks), b);
    }
    pairs++;
  }
}
console.log(`Exhaustive minimality, ordering, coordinates, context merging, frozen-input roundtrips: ${pairs} pairs, ${pairs * 4} patches`);

const source = Object.freeze(['a', 'b', 'c', 'd']);
const base = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
const malformed = [
  null, {}, { ...base, oldStart: 0 }, { ...base, oldStart: 2.5 },
  { ...base, newStart: 0 }, { ...base, newStart: 3 },
  { ...base, oldStart: 6 }, { ...base, oldLines: -1 },
  { ...base, oldLines: 2 }, { ...base, newLines: 2 },
  { ...base, newLines: -1 }, { ...base, lines: ['-wrong', '+B'] },
  { ...base, lines: [' wrong'] }, { ...base, lines: ['?b'] },
  { ...base, lines: [''] }, { ...base, lines: [null] },
  { ...base, lines: ['-b', '-c', '+B'] },
  { ...base, lines: ['-b', '+B', '+C'] },
  { ...base, lines: '-b' }, { ...base, oldStart: NaN },
];
for (const hunk of malformed) assert.throws(() => applyHunks(source, [hunk]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(source, [base, base]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(source, [base, { oldStart: 3, oldLines: 2, newStart: 3, newLines: 2, lines: [' c', ' wrong'] }]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(source, [base, { oldStart: 1, oldLines: 1, newStart: 1, newLines: 0, lines: ['-a'] }]), /hunk 1 does not apply/);
assert.deepEqual(applyHunks(source, [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] }, { oldStart: 3, oldLines: 1, newStart: 4, newLines: 0, lines: ['-c'] }]), ['top', 'a', 'b', 'd']);
assert.notEqual(applyHunks(source, []), source);
console.log('Malformed hunk rejection, original-coordinate offsets, and copy semantics: passed');

for (const repeated of [false, true]) {
  const a = Array.from({ length: 20000 }, (_, i) => repeated ? 'repeat' : `line ${i}`);
  const b = a.slice();
  b[50] = 'replacement';
  b.splice(10000, 1, 'insert one', 'insert two');
  b.splice(19000, 1);
  const start = performance.now();
  const script = diffLines(a, b);
  assert.equal(script.filter(e => e.op !== 'equal').length, 7);
  assert.deepEqual(applyHunks(a, unifiedHunks(a, b)), b);
  const elapsed = performance.now() - start;
  assert.ok(elapsed < 1000, `${elapsed}ms exceeds one second`);
  console.log(`20,000 ${repeated ? 'repeated' : 'unique'} lines: diff + hunks + application ${elapsed.toFixed(2)}ms`);
}

