'use strict';
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');
const source = Object.freeze(['a', 'b', 'c', 'd']);
assert.deepEqual(applyHunks(source, [
  { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] },
  { oldStart: 3, oldLines: 1, newStart: 3, newLines: 0, lines: ['-c'] },
]), ['top', 'a', 'b', 'd']);
assert.notEqual(applyHunks(source, []), source);
console.log('Original-coordinate offsets and copy semantics: passed');
for (const repeated of [false, true]) {
  const a = Array.from({ length: 20000 }, (_, i) => repeated ? 'repeat' : `line ${i}`);
  const b = a.slice();
  b[50] = 'replacement';
  b.splice(10000, 1, 'insert one', 'insert two');
  b.splice(19000, 1);
  const start = performance.now();
  const script = diffLines(a, b);
  assert.equal(script.filter(e => e.op !== 'equal').length, 6);
  assert.deepEqual(applyHunks(a, unifiedHunks(a, b)), b);
  const elapsed = performance.now() - start;
  assert.ok(elapsed < 1000, `${elapsed}ms exceeds one second`);
  console.log(`20,000 ${repeated ? 'repeated' : 'unique'} lines: diff + hunks + application ${elapsed.toFixed(2)}ms`);
}

